const INT=["Communication & Public Speaking","Future Programs","Just want to know more"];
const fld=(id,l,t,extra="",hint="")=>`<div class="f"><label for="${id}">${l}</label><input id="${id}" name="${id}" type="${t}" ${extra}><p class="er" id="e-${id}"></p>${hint?`<p class="hint">${hint}</p>`:""}</div>`;
let role=null;
function buildCb(){const p=role==="parent";$("#cb").innerHTML=
 (p?fld("studentName","Student’s Name","text",'autocomplete="off"')+fld("age","Student’s Age","number",'min="3" max="99" inputmode="numeric"')+fld("guardianName","Parent/Guardian’s Name","text",'autocomplete="name"')
  :fld("name","Your Name","text",'autocomplete="name"')+fld("age","Your Age","number",'min="3" max="99" inputmode="numeric"'))
 +fld("phone","Phone / WhatsApp Number","tel",'autocomplete="tel"',"(No spamming. Pinky promise.)")+fld("email","Email (optional)","email",'autocomplete="email"')
 +`<fieldset><legend>Interested in:</legend><div class="ch">${INT.map((x,i)=>`<label><input type="radio" name="interest" value="${x.replace("&","&amp;")}" ${i==0?"checked":""}><span>${x.replace("&","&amp;")}</span></label>`).join("")}</div></fieldset><button class="btn" style="width:100%" type="submit">GET A CALLBACK</button><div id="cb-m" role="status"></div>`}
function validate(form,rules){let ok=true,first;rules.forEach(([n,test,msg])=>{const i=form.elements[n];if(!i)return;const e=$("#e-"+i.id,form),bad=!test(i.value.trim());i.setAttribute("aria-invalid",bad);if(e){e.textContent=bad?msg:"";i.setAttribute("aria-describedby","e-"+i.id)}if(bad){ok=false;first=first||i}});first&&first.focus();return ok}
const R={name:v=>v.length>1,age:v=>+v>=3&&+v<=99,phone:v=>/^\+?[\d\s-]{10,15}$/.test(v),email:v=>!v||/^\S+@\S+\.\S+$/.test(v)};
const msg=(el,c,t)=>el.innerHTML=`<div class="msg ${c}">${t}</div>`;
function bindCb(){sending=false;const w=$("#cbw"),ri=$(".ri",w);role=null;ri.inert=true;
 $$("[data-r]").forEach(b=>b.onclick=()=>{role=b.dataset.r;$$("[data-r]").forEach(x=>x.setAttribute("aria-pressed",x===b));ri.classList.remove("in");buildCb();ri.inert=false;w.classList.add("open");requestAnimationFrame(()=>requestAnimationFrame(()=>ri.classList.add("in")));setTimeout(()=>{const f=$("#cb input");f&&f.focus({preventScroll:true})},500)});
 $("#cb").onsubmit=async e=>{e.preventDefault();const f=e.target,p=role==="parent";
  if(!validate(f,[[p?"studentName":"name",R.name,"Please enter a name."],["age",R.age,"Enter an age between 3 and 99."],...(p?[["guardianName",R.name,"Please enter the guardian’s name."]]:[]),["phone",R.phone,"Enter a valid phone number (10–15 digits)."],["email",R.email,"Enter a valid email."]]))return;
  const v=Object.fromEntries(new FormData(f)),m=$("#cb-m"),c={phone:v.phone.trim(),email:v.email.trim()||null,interested_in:v.interest};
  const row=p?{user_type:"parent_guardian",student_name:v.studentName.trim(),student_age:+v.age,parent_guardian_name:v.guardianName.trim(),...c}:{user_type:"student",name:v.name.trim(),age:+v.age,...c};
  if(sending)return;
  const btn=$("button[type=submit]",f);sending=true;btn.disabled=true;btn.setAttribute("aria-busy","true");
  try{if(!supabase)throw new Error("not configured");const {error}=await supabase.from("callback_submissions").insert(row);if(error)throw error;
   f.innerHTML=`<div class="done"><h3>You’re on our list.</h3><p>Thanks for reaching out to AceMyself. We’ll get back to you soon.</p></div>`}
  catch{console.error("Callback submission failed");sending=false;btn.disabled=false;btn.removeAttribute("aria-busy");msg(m,"no","Something went wrong. Please try again.")}}}
function loadRzp(){return new Promise((res,rej)=>{if(window.Razorpay)return res();const s=document.createElement("script");s.src="https://checkout.razorpay.com/v1/checkout.js";s.onload=res;s.onerror=rej;document.head.appendChild(s)})}
function bindEnroll(){$("#en").onsubmit=async e=>{e.preventDefault();const f=e.target,m=$("#en-m");
 if(!validate(f,[["name",R.name,"Please enter a name."],["phone",R.phone,"Enter a valid phone number."],["email",R.email,"Enter a valid email."]]))return;
 if(!CONFIG.api.createOrder||!CONFIG.api.razorpayKeyId)return msg(m,"no","Online payment isn’t connected yet — nothing was charged. Please check back soon or contact us.");
 const d=Object.fromEntries(new FormData(f));
 try{ /* server creates the order using the price from its own program config */
  const o=await(await fetch(CONFIG.api.createOrder,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({program:PR.slug,...d})})).json();
  await loadRzp();
  new Razorpay({key:CONFIG.api.razorpayKeyId,order_id:o.orderId,amount:o.amount,currency:PR.currency,name:B.name,description:`${PR.cohort} — ${PR.name}`,prefill:{name:d.name,contact:d.phone,email:d.email},
   handler:async r=>{const v=await fetch(CONFIG.api.verifyPayment,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(r)});v.ok?location.hash="#/payment-success":msg(m,"no","We couldn’t verify your payment. Please contact us.")}}).open()
 }catch{msg(m,"no","Couldn’t start payment. Please try again.")}}}
function bindFaq(){$$(".acc button").forEach(b=>b.onclick=()=>{const o=b.getAttribute("aria-expanded")==="true";b.setAttribute("aria-expanded",!o);$("#"+b.getAttribute("aria-controls")).hidden=o})}
/* ============ router ============ */
const TITLES={"/":"AceMyself — Learn. Grow. Ace.","/programs":"Programs","/about":"About","/faq":"FAQ","/contact":"Contact Us","/payment-success":"You’re in!","/privacy-policy":"Privacy Policy","/terms":"Terms & Conditions","/callback":"Get a Callback","/enroll":"Join the Cohort"};
let pend=false;
function route(){setMenu(false);let p=(location.hash.slice(1)||"/").replace(/\/$/,"")||"/";const cb=false;
 if(p.startsWith("/enroll"))p="/enroll";
 const fn=pages[p]||pages["/"];$("#app").innerHTML=fn();
 document.title=(TITLES[p]||PR.name)+(p==="/"?"":" | AceMyself");
 $$("nav a[href]:not(.btn)").forEach(a=>a.getAttribute("href")==="#"+p?a.setAttribute("aria-current","page"):a.removeAttribute("aria-current"));
 if($("#cb"))bindCb();if($("#en"))bindEnroll();if($(".acc"))bindFaq();
 if(cb)setTimeout(()=>$("#callback").scrollIntoView({behavior:"smooth"}),50);else window.scrollTo(0,0)}
document.addEventListener("click",e=>{if(e.target.closest("nav a, footer a, .hero a"))setMenu(false)});
addEventListener("hashchange",route);route();
